const test = require('node:test');
const assert = require('node:assert/strict');
const { retry } = require('./retry');

test('resolves with the first success', async () => {
  assert.equal(await retry(async () => 'ok', { sleep: async () => {} }), 'ok');
});

test('retries until it works', async () => {
  let calls = 0;
  const value = await retry(async () => { calls++; if (calls < 3) throw new Error('no'); return calls; }, { sleep: async () => {} });
  assert.equal(value, 3);
});

test('validates fn is a function', async () => {
  await assert.rejects(retry('not a function'), TypeError);
});

test('validates retries option', async () => {
  await assert.rejects(retry(async () => {}, { retries: -1 }), RangeError);
  await assert.rejects(retry(async () => {}, { retries: 1.5 }), RangeError);
  await assert.rejects(retry(async () => {}, { retries: '3' }), RangeError);
});

test('validates delayMs option', async () => {
  await assert.rejects(retry(async () => {}, { delayMs: -1 }), RangeError);
  await assert.rejects(retry(async () => {}, { delayMs: NaN }), RangeError);
  await assert.rejects(retry(async () => {}, { delayMs: Infinity }), RangeError);
});

test('validates factor option', async () => {
  await assert.rejects(retry(async () => {}, { factor: 0.9 }), RangeError);
  await assert.rejects(retry(async () => {}, { factor: NaN }), RangeError);
  await assert.rejects(retry(async () => {}, { factor: Infinity }), RangeError);
});

test('shouldRetry stops retrying when returning false', async () => {
  let attempts = 0;
  await assert.rejects(
    retry(async () => { attempts++; throw new Error('stop'); }, {
      retries: 3,
      shouldRetry: (err) => err.message !== 'stop',
      sleep: async () => {}
    }),
    /stop/
  );
  assert.equal(attempts, 1);
});

test('calculates backoff delays correctly', async () => {
  const waits = [];
  let attempts = 0;
  await retry(
    async () => {
      attempts++;
      if (attempts < 3) throw new Error('fail');
      return 'success';
    },
    {
      retries: 3,
      delayMs: 100,
      factor: 2,
      sleep: async (ms) => { waits.push(ms); }
    }
  );
  assert.deepEqual(waits, [100, 200]);
});
